WITH filtered_departments AS (SELECT * FROM departments WHERE location = 'Singapore'), budget_bucket_summary AS (SELECT CASE WHEN budget >= 3781000 THEN 'high' WHEN budget >= 1895000 THEN 'mid' ELSE 'low' END AS budget_bucket, CASE WHEN location IN ('Bangkok', 'London') THEN 'group_a' ELSE 'other' END AS location_group, COUNT(budget) AS budget_count FROM filtered_departments GROUP BY CASE WHEN budget >= 3781000 THEN 'high' WHEN budget >= 1895000 THEN 'mid' ELSE 'low' END, CASE WHEN location IN ('Bangkok', 'London') THEN 'group_a' ELSE 'other' END) SELECT budget_bucket, location_group, budget_count FROM budget_bucket_summary WHERE budget_count < 6
